(x, y, t) => {
  const cx = 240, cy = 120;
  const wells = [
    [160+Math.sin(t*0.4)*120, 80+Math.cos(t*0.3)*70, 180],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.6)*80, 220],
    [240+Math.sin(t*0.25+2)*150, 120+Math.cos(t*0.45+1)*100, 160],
    [100+Math.cos(t*0.7+1)*90, 200+Math.sin(t*0.5+3)*60, 140],
    [380+Math.sin(t*0.35+4)*100, 50+Math.cos(t*0.8+2)*80, 200],
    [240+Math.cos(t*0.3+5)*130, 220+Math.sin(t*0.4)*70, 170],
    [60+Math.sin(t*0.55)*60, 40+Math.cos(t*0.65)*40, 120],
    [420+Math.cos(t*0.45)*50, 200+Math.sin(t*0.75)*50, 130]
  ];
  let gx = 0, gy = 0, pot = 0;
  for (const [wX, wY, mass] of wells) {
    const dx = wX - x, dy = wY - y;
    const d2 = dx*dx + dy*dy + 100;
    const d = Math.sqrt(d2);
    const force = mass / d2;
    gx += dx * force * 0.8;
    gy += dy * force * 0.8;
    pot += mass / d;
  }
  const wx = Math.sin(y*0.018+t*0.3)*12 + Math.cos(x*0.012-t*0.2)*8;
  const wy = Math.cos(x*0.016-t*0.25)*12 + Math.sin(y*0.014+t*0.35)*8;
  const sx = x + gx*0.15 + wx, sy = y + gy*0.15 + wy;
  let act = 0, inh = 0, energy = 0;
  for (const [sX, sY, mass] of wells) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const f = 0.06 + mass*0.00015, sp = 1.5 + mass*0.005;
    act += Math.sin(d*f - t*sp) * (mass/180);
    inh += Math.sin(d*f*0.6 + t*sp*0.5 + 1.2) * (mass/180);
    energy += Math.cos(d*f*0.4 - t*sp*0.3 + 2.0) * (mass/180);
  }
  act /= 3; inh /= 3; energy /= 3;
  const turb = (Math.sin(sx*0.05+sy*0.03+t*1.2)*Math.cos(sx*0.03-sy*0.05+t*0.9) + Math.sin((sx+sy)*0.08+t*2.0)*Math.cos((sx-sy)*0.06-t*1.5))*0.5;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.04-ang*4-t*1.8) + Math.sin(dist*0.035+ang*5-t*1.3) + Math.sin(dist*0.06-ang*2+t*0.7))*0.33;
  const kinetic = Math.sqrt(gx*gx + gy*gy) * 0.012;
  const conserved = Math.sin(act*2.5 + inh*1.8 + spiral*1.5 + turb + energy*0.8 + kinetic);
  const reaction = Math.tanh(conserved * 2.8);
  const edge = 1.0 - Math.pow(Math.abs(reaction), 8) * 0.15;
  const glow = Math.pow(Math.max(0, Math.abs(reaction) - 0.5) * 2, 2) * 0.6;
  const v = reaction * edge * 0.5 + 0.5;
  const neon = [
    [2, 2, 12],
    [5, 10, 45],
    [0, 60, 120],
    [0, 180, 220],
    [0, 255, 200],
    [180, 255, 100],
    [255, 220, 50],
    [255, 80, 120],
    [220, 30, 180],
    [120, 10, 160],
    [30, 5, 60],
    [2, 2, 12]
  ];
  const idx = v * (neon.length - 1), i = Math.min(idx|0, neon.length-2), f = idx - i;
  const c0 = neon[i], c1 = neon[i+1];
  const lum = 0.7 + glow * 0.8;
  const hot = glow > 0.3 ? 1.0 + (glow - 0.3) * 0.5 : 1.0;
  return [
    Math.min(255, ((c0[0]+(c1[0]-c0[0])*f)*lum*hot + glow*40)|0),
    Math.min(255, ((c0[1]+(c1[1]-c0[1])*f)*lum*hot + glow*60)|0),
    Math.min(255, ((c0[2]+(c1[2]-c0[2])*f)*lum*hot + glow*50)|0)
  ];
}
